import React from 'react';
import classNames from 'classnames';
import { UI } from '@deprecated/types';
import './MicrophoneBadge.less';
import { MicrophoneIcon } from './MicrophoneIcon';

interface MicrophoneBadgeProps {
  hubPosition: UI.HubPosition;
}

export const MicrophoneBadge: React.FC<MicrophoneBadgeProps> = ({ hubPosition }) => {
  return (
    <div
      className={classNames('microphone-badge', {
        left: hubPosition.horizontal === UI.HorizontalHubPosition.Left,
        right: hubPosition.horizontal === UI.HorizontalHubPosition.Right,
      })}
      data-testid="microphone-badge"
      aria-label="Listening"
      role="status"
    >
      <MicrophoneIcon />
    </div>
  );
};

MicrophoneBadge.displayName = 'MicrophoneBadge';

export default MicrophoneBadge;
